N=16
rows=[[8]*N for _ in range(N)]
pts={4:(0,5),9:(2,6),0:(6,14),-8:(8,15)} # k -> inclusive row range, from visual
# compute cells between adjacent active diagonal segments in (u=r+c, v=c-r)
for r in range(N):
    for c in range(N):
        u=r+c; v=c-r
        active=sorted(k for k,(r0,r1) in pts.items() if 2*r0+k <= u <= 2*r1+k)
        if any(a < v < b for a,b in zip(active,active[1:])):
            rows[r][c]=2
for k,(r0,r1) in pts.items():
    for r in range(r0,r1+1):
        rows[r][r+k]=9
print('\n'.join(' '.join(map(str,row)) for row in rows))
